INSERT INTO fcc_agent_endpoint_binding(
  id, agent_id, endpoint_type, extension_id, endpoint_value, priority, is_active, status
)
SELECT #{id}, a.id, 'SIP', e.id, e.extension, 0, 1, 'ENABLED'
FROM fcc_agent a
JOIN fcc_extension e ON e.extension = #{extension}
WHERE a.work_no = #{owner}
  AND a.deleted_at IS NULL
  AND e.deleted_at IS NULL
